components.css:
.ds-purpose-ledger { max-width: 56rem; color: var(--color-text); font-family: var(--font-sans); line-height: 1.5; }
.ds-sphere { border-block: 1px solid var(--color-border); }
.ds-sphere + .ds-sphere { border-top: 0; }
.ds-sphere-summary, .ds-support-summary { list-style: none; cursor: pointer; border-radius: 8px; transition: background-color 150ms, color 150ms; }
.ds-sphere-summary::-webkit-details-marker, .ds-support-summary::-webkit-details-marker { display: none; }
.ds-sphere-summary { display: grid; grid-template-columns: minmax(0,1fr) auto 1rem; min-height: 64px; box-sizing: border-box; align-items: center; gap: 12px; padding: 12px; }
.ds-sphere-name { min-width: 0; overflow-wrap: anywhere; font-size: 16px; font-weight: 500; }
.ds-total { display: inline-flex; justify-content: flex-end; align-items: center; gap: 4px; text-align: right; white-space: nowrap; font-family: var(--font-mono); font-size: 14px; line-height: 20px; font-weight: 400; font-variant-numeric: tabular-nums; }
.ds-chevron { width: 16px; height: 16px; flex-shrink: 0; color: var(--color-text-muted); }
.ds-sphere[open] > .ds-sphere-summary > .ds-chevron, .ds-support[open] > .ds-support-summary > .ds-chevron { rotate: 180deg; }
.ds-sphere-summary:hover, .ds-support-summary:hover { background: var(--color-surface-hover); color: var(--color-text); }
.ds-sphere-summary:active, .ds-support-summary:active { background: var(--color-surface-active); }
.ds-sphere-summary:focus-visible, .ds-support-summary:focus-visible, .ds-sphere-action:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }
.ds-sphere-content { display: flex; flex-direction: column; gap: 16px; padding: 4px 12px 16px; }
.ds-currencies { width: 100%; max-width: 24rem; margin: 0; }
.ds-currencies > div { display: grid; grid-template-columns: minmax(0,1fr) auto; align-items: baseline; column-gap: 16px; }
.ds-currencies > div + div { margin-top: 8px; }
.ds-currencies dt { color: var(--color-text-muted); font-size: 12px; line-height: 16px; }
.ds-currencies dd { margin: 0; text-align: right; font-family: var(--font-mono); font-size: 16px; line-height: 24px; font-weight: 400; font-variant-numeric: tabular-nums; }
.ds-actions { display: flex; flex-direction: column; gap: 12px; }
.ds-money-actions { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 8px; }
.ds-sphere-action { height: 44px; padding: 0 8px; border: 1px solid var(--color-border); border-radius: 8px; background: var(--color-surface); color: var(--color-text); font-family: var(--font-sans); font-size: 14px; white-space: nowrap; cursor: pointer; transition: background-color 150ms, box-shadow 150ms; }

.ds-sphere-action:disabled { background: var(--color-surface-muted); cursor: default; }
.ds-manage { align-self: flex-start; }
.ds-support { margin-top: 24px; }
.ds-support-summary { display: flex; min-height: 44px; box-sizing: border-box; align-items: center; justify-content: space-between; gap: 12px; padding: 8px 12px; color: var(--color-text-muted); font-size: 14px; }
.ds-support p { max-width: 65ch; color: var(--color-text-muted); font-size: 14px; }
.ds-warning { color: var(--color-warning); }
.ds-warning-icon { width: 14px; height: 14px; flex-shrink: 0; }
.ds-sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
@media (min-width: 640px) { .ds-actions { flex-direction: row; align-items: center; } .ds-money-actions { display: flex; } .ds-manage { margin-left: auto; } .ds-sphere-action { height: 36px; padding-inline: 12px; } }
@media (prefers-reduced-motion: reduce) { .ds-sphere-summary, .ds-support-summary, .ds-sphere-action { transition: none; } } @media (prefers-reduced-motion: reduce) { button, input, select { transition: none; } }
